  25:     public PipelineProxy(TransformCompiler compiler) {
  26:         this.compiler = compiler;
  27:     }
  28: 
  29:     public PipelineExecutor createExecutor() {
  30:         return (PipelineExecutor) Proxy.newProxyInstance(
  31:                 PipelineExecutor.class.getClassLoader(),
  32:                 new Class[]{PipelineExecutor.class},
  33:                 (proxy, method, args) -> dispatch((DecryptContext) args[0])
  34:         );
