  38:         byte[] transformed = compiler.compile(ctx.sessionKey()).applyTransform(ctx.ciphertext());
  39:         UnaryOperator<byte[]> finalize = data -> Arrays.copyOf(data, data.length);
  40:         return finalize.apply(transformed);
  41:     }
