   1: package com.example.truth.handler;
   2: 
   3: import net.bytebuddy.ByteBuddy;
   4: import net.bytebuddy.NamingStrategy;
   5: import net.bytebuddy.dynamic.loading.ClassLoadingStrategy;
   6: import net.bytebuddy.implementation.FixedValue;
   7: import net.bytebuddy.matcher.ElementMatchers;
   8: import org.springframework.stereotype.Component;
   9: 
  10: import java.io.IOException;
  11: import java.io.InputStream;
  12: import java.util.Properties;
  13: import java.util.concurrent.ConcurrentHashMap;
  14: 
  15: /**
  16:  * Compiles a TransformHandler for a given sessionKey by:
  17:  *   1. Computing a transform index via a polynomial rolling hash of the sessionKey.
  18:  *   2. Looking up the XOR key for that index in transform-keys.properties.
  19:  *   3. Generating a concrete subclass of TransformBase with the key baked in
  20:  *      as a constant using ByteBuddy.
  21:  *
  22:  * The generated class name includes the transform index (e.g. TransformBase$Transform037$...)
  23:  * so that monitoring tools can correlate a running handler back to its config entry.
  24:  */
  25: @Component
  26: public class TransformCompiler {
  27: 
  28:     private static final String KEYS_CONFIG     = "transform-config/transform-keys.properties";
  29:     private static final String SELECTOR_CONFIG = "transform-config/selector-config.properties";
  30:     private static final int    HASH_MULTIPLIER = 31;
  31:     private static final int    TRANSFORM_COUNT = 50;
  32: 
  33:     private final int        hashSeed;
  34:     private final Properties transformKeys;
  35:     private final ConcurrentHashMap<String, TransformHandler> cache = new ConcurrentHashMap<>();
  36: 
  37:     public TransformCompiler() throws IOException {
  38:         Properties selector = new Properties();
  39:         try (InputStream in = TransformCompiler.class.getClassLoader()
  40:                 .getResourceAsStream(SELECTOR_CONFIG)) {
  41:             if (in == null) throw new IOException(SELECTOR_CONFIG + " not found");
  42:             selector.load(in);
  43:         }
  44:         this.hashSeed = Integer.parseInt(selector.getProperty("transform.hash.seed"));
  45: 
  46:         this.transformKeys = new Properties();
  47:         try (InputStream in = TransformCompiler.class.getClassLoader()
  48:                 .getResourceAsStream(KEYS_CONFIG)) {
  49:             if (in == null) throw new IOException(KEYS_CONFIG + " not found");
  50:             transformKeys.load(in);
  51:         }
  52:     }
  53: 
  54:     public TransformHandler compile(String sessionKey) throws Exception {
  55:         return cache.computeIfAbsent(sessionKey, k -> {
  56:             try {
  57:                 return doCompile(k);
  58:             } catch (Exception e) {
  59:                 throw new RuntimeException("Compilation failed for sessionKey=" + k, e);
  60:             }
  61:         });
  62:     }
  63: 
  64:     private TransformHandler doCompile(String sessionKey) throws Exception {
  65:         int index = selectTransform(sessionKey);
  66:         String keyProp = String.format("transform.%03d", index);
  67:         int keyValue = Integer.parseInt(transformKeys.getProperty(keyProp));
  68: 
  69:         String transformTag = String.format("Transform%03d", index);
  70: 
  71:         Class<?> generated = new ByteBuddy()
  72:                 .with(new NamingStrategy.SuffixingRandom(transformTag))
  73:                 .subclass(TransformBase.class)
  74:                 .method(ElementMatchers.named("getKey"))
  75:                 .intercept(FixedValue.value(keyValue))
  76:                 .make()
  77:                 .load(TransformCompiler.class.getClassLoader(),
  78:                       ClassLoadingStrategy.Default.INJECTION)
  79:                 .getLoaded();
  80: 
  81:         return (TransformHandler) generated.getDeclaredConstructor().newInstance();
  82:     }
  83: 
  84:     /**
  85:      * Maps a sessionKey to a transform index in [1, TRANSFORM_COUNT].
  86:      * Uses a polynomial rolling hash with configurable seed for reproducible
  87:      * transform assignment across all service instances.
  88:      */
  89:     private int selectTransform(String sessionKey) {
  90:         int h = hashSeed;
  91:         for (char c : sessionKey.toCharArray()) {
  92:             h = h * HASH_MULTIPLIER + c;
  93:         }
  94:         return (Math.abs(h) % TRANSFORM_COUNT) + 1;
  95:     }
  96: }
